class TinyGPT:
    def __init__(self):
        # Map each word -> {next_word: count}
        self.bigrams = {}

    def train(self, text: str):
        words = text.lower().split()
        for a, b in zip(words, words[1:]):
            nxt = self.bigrams.setdefault(a, {})
            nxt[b] = nxt.get(b, 0) + 1

    def predict_next(self, word: str):
        nxt = self.bigrams.get(word)
        if not nxt:
            return None
        best = None
        best_count = 0
        for w, c in nxt.items():  # dicts keep insertion order -> ties go to first seen
            if c > best_count:
                best, best_count = w, c
        return best

    def generate(self, start_word: str, n: int = 5) -> list:
        result = [start_word]
        while len(result) < n:
            nxt = self.predict_next(result[-1])
            if nxt is None:
                break
            result.append(nxt)
        return result


# Test it:
gpt = TinyGPT()
gpt.train("the cat sat on the mat the cat ran")

print(gpt.predict_next("the"))   # 'cat' (appears most after 'the')
print(gpt.predict_next("cat"))   # 'sat' or 'ran' (tie -> first seen)
print(gpt.predict_next("zebra")) # None
print(gpt.generate("the", 4))
